"""Day 18：检索 Retriever —— 向量化问题 → 查库 → 取 Top-K。"""
import os
from pathlib import Path
from dotenv import load_dotenv
from openai import OpenAI
import chromadb
import logging
from functools import lru_cache
import chromadb
from openai import OpenAI


@lru_cache(maxsize=1)
def _embed_client() -> OpenAI:
    """embedding 客户端只建一次。

    OpenAI 客户端内部维护连接池，是设计成复用的。
    每次新建 = 每次重连 = 每次重新握手。
    """
    return OpenAI(
        api_key=os.environ["DASHSCOPE_API_KEY"],   # ← 换成你现在的写法
        base_url="https://dashscope.aliyuncs.com/compatible-mode/v1",  # ← 同上
    )


@lru_cache(maxsize=1)
def _chroma_client() -> chromadb.ClientAPI:
    """chromadb 客户端也只建一次。"""
    return chromadb.PersistentClient(path=DB_PATH)
logger = logging.getLogger(__name__)

# ===== 0. 配置（这些常量必须和入库时完全一致）=====
PROJECT_ROOT = Path(r"D:\ai-qa-assistant")
DB_PATH = str(PROJECT_ROOT / "chroma_db")

# 极其重要：COLLECTION_NAME 和 EMBEDDING_MODEL 必须与 Day 17 完全一样！
# 如果你入库用的是 v4 模型，检索时换成了别的模型，算出来的坐标系完全不在一个维度上。
COLLECTION_NAME = "rag_notes_v2"
EMBEDDING_MODEL = "text-embedding-v4"

# 设定每次只返回最相关的 3 条结果，控制后续传给大模型的上下文长度
TOP_K = 3

# 加载 .env 文件中的环境变量（API Key 等）
load_dotenv(PROJECT_ROOT / ".env")


# ===== 1. 把问题向量化 =====
def embed_query(question: str) -> list[float]:
    """把用户问题转成一个向量。"""
    # 创建一个临时的 API 客户端。这次不是为了算几千个块，而是为了算用户的一句话。
    client = _embed_client()
    # 发起请求。
    # 为什么 input 必须传列表 [question]？因为阿里云 API 规定 input 必须是批量的（可以一次传多个），
    # 哪怕你只有一句，也得用方括号包成列表。单条查询不需要分批，不会触发限流。
    resp = client.embeddings.create(
        model=EMBEDDING_MODEL,
        input=[question],
        dimensions=1024
    )
