# ===== 2. 查库，取 Top-K =====
def retrieve(
    question: str,
    k: int = TOP_K,
    where: dict | None = None,  # 留了一手：未来可以做“过滤查询”，比如只搜 source='笔记.txt' 的内容
        # 你要在哪个范围里查（精准过滤，避免语义污染）
    collection: str = COLLECTION_NAME,
) -> list[dict]:
    """检索：向量化问题 → 查库 → 返回 Top-K 条结果。"""

    # 1) 打开本地硬盘上的数据库，拿到你昨天存好的 rag_notes 集合（表）
    chroma = _chroma_client()
    col = chroma.get_collection(collection)

    # 2) 调用上面的函数，把用户的文字变成 1024 维的探照灯
    query_vec = embed_query(question)

    # 3) 数据库搜索
    # 注意大坑：query_embeddings 要求传一个二维列表 [[0.1, 0.2...]]。
    # 因为底层允许你一次传 10 个问题同时搜，哪怕你只搜 1 个，也得用 [] 包起来。
    res = col.query(
        # 是 Chroma 数据库专门提供的相似度搜索方法。
        query_embeddings=[query_vec],
        # query_vec：是问题通过 API 算出来的一维向量，形如 [0.12, -0.45, ...]（1024个数字）。
        n_results=k,
        # 设定每次只返回最相关的 3 条结果，控制后续传给大模型的上下文长度
        where=where
    )

    # 4) 解析返回结果（把两层嵌套拍平）
    hits = []
    # 检查返回结果里有没有东西
    # res["ids"][0]：因为返回的是两层嵌套（外层代表你的第几个问题，内层代表 Top-K），
    # 所以必须取 [0] 进入第一道门。
    if res["ids"] and res["ids"][0]:
        # {'ids': [['02_网络协议笔记.txt::0', '02_网络协议笔记.txt::2', '02_网络协议笔记.txt::1']], 'embeddings': None,
        #  'documents': [
        #      ['TCP 三次握手\n第一次：客户端发送 SYN=1，序号 seq=x\n第二次：服务端返回 SYN=1，ACK=1，seq=y，ack=x+1\n第三次：客户端发送 ACK=1，ack=y+1',
        #       '。\n如果只有两次，服务端无法确认客户端的接收能力，也无法防止历史连接请求造成的错误。',
        #       '为什么是三次而不是两次：为了确认双方的收发能力都正常']], 'uris': None,
        #  'included': ['metadatas', 'documents', 'distances'], 'data': None,
        #  'metadatas': [
        #     [{'source': '02_网络协议笔记.txt'}, {'source': '02_网络协议笔记.txt'}, {'source': '02_网络协议笔记.txt'}]],
        #  'distances': [[0.0, 0.37685900926589966, 0.38716739416122437]]}

        for i in range(len(res["ids"][0])):
            # Day 18 最重要的公式！
            # Chroma 返回的 distance 是余弦距离（0 表示完全一样，数值越大越远）。
            # 为了迎合人类直觉（100% 满分），这里做了转换：相似度 = 1 - 距离。
            # 换算后，0.9 就代表 90% 相似，越接近 1 越好。
            distance = res["distances"][0][i]
            similarity = 1 - distance

            # 把散落的数据打包成一个整洁的字典，以后丢给大模型直接读
            hits.append({
                "id": res["ids"][0][i],
                "text": res["documents"][0][i],
                "score": similarity,  # 这里存的是相似度，不是距离！
                "metadata": res["metadatas"][0][i]
            })
            # hits是一个集合（存放回答）每一个集合中包含了四个键值对 , 即[{"id": , "text": , "score": , "metadata": }]

            # 灾难性的代码耦合。底层数据库从 Chroma 换成了 Milvus，或者 Pinecone。它们返回的 res 结构完全不一样！ res["ids"][0][i] 瞬间全部报错。
            # 大模型看不懂。它不认识嵌套那么深的二维数组。

    top_score = max((h["score"] for h in hits), default=0.0)
    logger.info(
        "检索 collection=%s k=%d 召回=%d 最高分=%.3f",
        collection, k, len(hits), top_score,
    )

    return hits


# ===== 3. 打印结果（给人看）=====
def print_hits(hits: list[dict], question: str) -> None:
    """把检索结果打印到屏幕上。"""
    print("=" * 60)
    print(f"❓ 用户问题：{question}")
    print("-" * 60)

    for i, hit in enumerate(hits):
        # 保留 4 位小数，让分数看起来更专业（比如 0.8732）
        score_str = f"{hit['score']:.4f}"

        source = hit['metadata'].get("source", "未知来源")

        # 把文本块里的换行符替换成空格。为什么？
        # 因为终端如果遇到换行符，输出的排版会全乱掉，变成一行一行断开的字。
        text_snippet = hit['text'][:60].replace('\n', ' ')

        print(f"[{i+1}] 相似度(similarity): {score_str} | 来源: {source}")
        print(f"    内容: {text_snippet}...")
        print()

    print(f"🎯 共召回 {len(hits)} 条")


if __name__ == "__main__":
    # 测试一个问题（根据你之前存的网络协议笔记，这里问点相关的）
    test_question = "RAG的完整链路"

    # 串起来：question -> retrieve -> print_hits
    # 模拟用户提问 -> 程序自动变成向量 -> 搜库找最像的 3 段话 -> 打印出来
    search_results = retrieve(test_question, k=TOP_K)
    print_hits(search_results, test_question)